<?php require 'includes/header.php';require 'config/db.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$sid=(int)$_POST['student_id'];$sub=(int)$_POST['subject_id'];$exam=$_POST['exam_name'];$marks=(float)$_POST['marks'];$grade=$marks>=80?'A':($marks>=70?'B':($marks>=60?'C':($marks>=50?'D':'F')));$q=$conn->prepare("INSERT INTO results(student_id,subject_id,exam_name,marks,grade) VALUES(?,?,?,?,?)");$q->bind_param('iisds',$sid,$sub,$exam,$marks,$grade);$q->execute();header('Location:results.php');exit;}
$students=$conn->query("SELECT id,student_id,first_name,last_name FROM students");$subjects=$conn->query("SELECT id,subject_name FROM subjects");$rows=$conn->query("SELECT r.*,s.first_name,s.last_name,sub.subject_name FROM results r JOIN students s ON s.id=r.student_id JOIN subjects sub ON sub.id=r.subject_id ORDER BY r.id DESC");?>
<h3 class="mb-3">Results</h3><div class="card p-3"><table class="table"><tr><th>Student</th><th>Subject</th><th>Exam</th><th>Marks</th><th>Grade</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r['first_name'].' '.$r['last_name']?></td><td><?=$r['subject_name']?></td><td><?=$r['exam_name']?></td><td><?=$r['marks']?></td><td><?=$r['grade']?></td></tr><?php endwhile;?></table></div>
